package com.edde746.plezy

import android.content.ComponentName
import android.content.Context
import android.content.pm.ActivityInfo
import android.content.pm.PackageManager
import android.os.Build
import android.util.Log
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel

/**
 * Switches the launcher icon and Android TV banner between the activity-aliases that target
 * [PlezyActivity]: `.MainActivity` is the default icon, `.appicon.<id>` are the Supporter
 * alternates generated by scripts/codegen/generate_app_icons.py. Exactly one alias is enabled.
 *
 * `.MainActivity` keeps the component name the launcher activity had before icons became
 * switchable, so home-screen shortcuts and TV favourites from older installs still resolve, and
 * every alias keeps its manifest state until the user picks another icon. Choosing the default
 * again puts every alias back to that state.
 */
internal class AppIconSwitcher(private val packageManager: PackageManager, private val packageName: String) {
  companion object {
    const val DEFAULT_ICON = "default"
    private const val DEFAULT_ALIAS_SUFFIX = ".MainActivity"
    private const val ALTERNATE_ALIAS_MARKER = ".appicon."
    private const val FEATURE_FIRE_TV = "amazon.hardware.fire_tv"
  }

  private class Change(val component: ComponentName, val state: Int, val enables: Boolean)

  /** Launcher aliases by icon id, read from the manifest so the generator's list is the only one. */
  private val aliases: Map<String, ActivityInfo> by lazy(LazyThreadSafetyMode.NONE) { loadAliases() }

  /**
   * Fire TV's launcher draws Appstore apps from their store listing art, and Android Automotive is
   * not a target for alternate icons; neither offers the picker. [INFERENCE] for Fire TV: no device
   * confirmed that its launcher follows an alias switch.
   */
  fun isSupported(): Boolean = !packageManager.hasSystemFeature(FEATURE_FIRE_TV) &&
    !packageManager.hasSystemFeature(PackageManager.FEATURE_AUTOMOTIVE) &&
    DEFAULT_ICON in aliases &&
    aliases.size > 1

  /**
   * The icon the launcher shows. A switch interrupted between its steps on API < 33 can leave the
   * default and an alternate both enabled; the alternate is the one the user picked last.
   */
  fun current(): String = aliases.entries.filter { (_, info) -> isEnabled(info) }.map { it.key }
    .firstOrNull { it != DEFAULT_ICON } ?: DEFAULT_ICON

  /** Enables [id]'s alias and disables the rest. False, changing nothing, when [id] is not an icon. */
  fun set(id: String): Boolean {
    if (id !in aliases) return false
    val changes = aliases.mapNotNull { (alias, info) ->
      val enable = alias == id
      val state = when {
        enable == info.enabled -> PackageManager.COMPONENT_ENABLED_STATE_DEFAULT
        enable -> PackageManager.COMPONENT_ENABLED_STATE_ENABLED
        else -> PackageManager.COMPONENT_ENABLED_STATE_DISABLED
      }
      val component = info.component()
      if (packageManager.getComponentEnabledSetting(component) == state) null else Change(component, state, enable)
    }
      // Enable before disabling: if the process dies part way through, the app keeps a launcher entry.
      .sortedByDescending { it.enables }
    if (changes.isEmpty()) return true
    // DONT_KILL_APP: the running task belongs to PlezyActivity, which is never disabled.
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
      // One atomic update and one package-changed broadcast, so launchers refresh once.
      packageManager.setComponentEnabledSettings(
        changes.map {
          PackageManager.ComponentEnabledSetting(it.component, it.state, PackageManager.DONT_KILL_APP)
        }
      )
    } else {
      for (change in changes) {
        packageManager.setComponentEnabledSetting(change.component, change.state, PackageManager.DONT_KILL_APP)
      }
    }
    return true
  }

  @Suppress("DEPRECATION")
  private fun loadAliases(): Map<String, ActivityInfo> {
    val activities = packageManager.getPackageInfo(
      packageName,
      PackageManager.GET_ACTIVITIES or PackageManager.MATCH_DISABLED_COMPONENTS
    ).activities ?: return emptyMap()
    return activities.mapNotNull { info -> iconId(info)?.let { it to info } }.toMap()
  }

  private fun iconId(info: ActivityInfo): String? {
    if (info.targetActivity == null) return null
    if (info.name.endsWith(DEFAULT_ALIAS_SUFFIX)) return DEFAULT_ICON
    val marker = info.name.lastIndexOf(ALTERNATE_ALIAS_MARKER)
    return if (marker < 0) null else info.name.substring(marker + ALTERNATE_ALIAS_MARKER.length)
  }

  private fun isEnabled(info: ActivityInfo): Boolean = when (packageManager.getComponentEnabledSetting(info.component())) {
    PackageManager.COMPONENT_ENABLED_STATE_ENABLED -> true
    PackageManager.COMPONENT_ENABLED_STATE_DEFAULT -> info.enabled
    else -> false
  }

  private fun ActivityInfo.component() = ComponentName(this.packageName, this.name)
}

/** `com.plezy/app_icon`: isSupported, getCurrent and setIcon({id}) over [AppIconSwitcher]. */
internal class AppIconChannel(private val context: Context) {
  companion object {
    private const val TAG = "AppIconChannel"
    private const val CHANNEL = "com.plezy/app_icon"
  }

  private val switcher by lazy(LazyThreadSafetyMode.NONE) {
    AppIconSwitcher(context.packageManager, context.packageName)
  }

  fun attach(messenger: BinaryMessenger) {
    MethodChannel(messenger, CHANNEL).setMethodCallHandler(::onMethodCall)
  }

  private fun onMethodCall(call: MethodCall, result: MethodChannel.Result) {
    try {
      when (call.method) {
        "isSupported" -> result.success(switcher.isSupported())
        "getCurrent" -> result.success(switcher.current())
        "setIcon" -> setIcon(call.argument<String>("id"), result)
        else -> result.notImplemented()
      }
    } catch (e: Exception) {
      Log.w(TAG, "${call.method} failed", e)
      result.error("failed", e.message, null)
    }
  }

  private fun setIcon(id: String?, result: MethodChannel.Result) {
    when {
      !switcher.isSupported() -> result.error("unsupported", "This launcher does not switch app icons", null)
      id == null || !switcher.set(id) -> result.error("unknown_icon", "No app icon with id $id", null)
      else -> result.success(null)
    }
  }
}
